import{_ as e,o as a,c as r,ag as d}from"./chunks/framework.4s5LDCII.js";const p=JSON.parse('{"title":"成人高尿酸血症与痛风食养指南（2024年版）","description":"国家卫健委《成人高尿酸血症与痛风食养指南（2024年版）》可执行整理：低嘌呤膳食的行动清单，每条出处可一键跳回原文对应页。","frontmatter":{"title":"成人高尿酸血症与痛风食养指南（2024年版）","issuer":"国家卫生健康委办公厅","source_tier":"一级来源","version":"2024年版","published":"2024-02","source_url":"https://www.nhc.gov.cn/wjw/c100378/202402/afd5dda4bd6745fda10aad8d43a16369/files/1732845129551_37712.pdf","status":"现行","tags":["痛风","高尿酸","食养","饮食指导","行动清单"],"reviewed":false,"description":"国家卫健委《成人高尿酸血症与痛风食养指南（2024年版）》可执行整理：低嘌呤膳食的行动清单，每条出处可一键跳回原文对应页。"},"headers":[],"relativePath":"guides/gout-2024.md","filePath":"guides/gout-2024.md"}'),g={name:"guides/gout-2024.md"};function h(o,t,i,s,u,l){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="成人高尿酸血症与痛风食养指南-2024年版" tabindex="-1">成人高尿酸血症与痛风食养指南（2024年版） <a class="header-anchor" href="#成人高尿酸血症与痛风食养指南-2024年版" aria-label="Permalink to &quot;成人高尿酸血症与痛风食养指南（2024年版）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据官方 PDF 原文整理，尚未逐条对照原文校验；校验通过前请以原文为准。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页所有建议均<strong>整理自官方文件原文</strong>，每条&quot;出处&quot;均可点击直达原文对应页；标注【本站提示】的少数条目为中性工具提示，不代表医学建议。本站不构成诊疗建议，与医生的治疗方案冲突时，<strong>以医嘱为准</strong>。</p></div><blockquote><p><strong>原文出处</strong>：国家卫生健康委办公厅印发（<a href="https://www.nhc.gov.cn/wjw/c100378/202402/afd5dda4bd6745fda10aad8d43a16369/files/1732845129551_37712.pdf" target="_blank" rel="noreferrer">官方全文 PDF（卫健委直链）</a>）· 一级来源。下文&quot;出处&quot;链接指向本站镜像的<a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf" target="_blank" rel="noreferrer">官方原文 PDF</a>（政府公文，属公共领域）。</p></blockquote><h2 id="这份文件适合谁" tabindex="-1">这份文件适合谁 <a class="header-anchor" href="#这份文件适合谁" aria-label="Permalink to &quot;这份文件适合谁&quot;">​</a></h2><p>成人高尿酸血症与痛风患者，以及尿酸偏高、有痛风家族史的人群及其家人；基层卫生工作者与营养指导人员亦可参考（<a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=3" target="_blank" rel="noreferrer">原文·前言</a>）。</p><h2 id="速览卡-一屏看完" tabindex="-1">速览卡（一屏看完） <a class="header-anchor" href="#速览卡-一屏看完" aria-label="Permalink to &quot;速览卡（一屏看完）&quot;">​</a></h2><p><strong>七条原则</strong>：食物多样、限制嘌呤 → 蔬奶充足、限制果糖 → 足量饮水、限制饮酒 → 科学烹饪、少食生冷 → 吃动平衡、健康体重 → 辨证辨体、因人施膳 → 因地因时、择膳相宜。（<a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=6" target="_blank" rel="noreferrer">原文·三</a>）</p><table tabindex="0"><thead><tr><th>关键数字（每日，除注明外）</th><th>数值</th><th>出处</th></tr></thead><tbody><tr><td>食物品种</td><td>每天 <strong>≥12 种</strong>、每周 <strong>≥25 种</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=6" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>全谷物</td><td>不低于主食量的 <strong>30%</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=6" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>膳食纤维</td><td><strong>25～30g</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=6" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>蔬菜</td><td><strong>≥500g</strong>，深色蔬菜（紫甘蓝、胡萝卜等）占一半以上</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>奶及奶制品</td><td><strong>300mL 以上</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>水果</td><td><strong>200～350g</strong>（果糖限制不针对整果水果）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>饮水</td><td><strong>2000～3000mL</strong>（心肾功能正常时），维持尿量 &gt;2000mL</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>食盐</td><td><strong>≤5g</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>烹调油</td><td><strong>25～30g</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>减重速度</td><td><strong>每周 0.5～1.0kg</strong>；每日少摄入 250～500kcal + 运动消耗 250～500kcal</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=9" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>运动</td><td>有氧<strong>每周 4～5 次、每次 30～60 分钟</strong>（低中强度起步）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=9" target="_blank" rel="noreferrer">三(五)</a></td></tr></tbody></table><h2 id="行动清单" tabindex="-1">行动清单 <a class="header-anchor" href="#行动清单" aria-label="Permalink to &quot;行动清单&quot;">​</a></h2><h3 id="🛒-买" tabindex="-1">🛒 买 <a class="header-anchor" href="#🛒-买" aria-label="Permalink to &quot;🛒 买&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>以低嘌呤膳食为主，食材科学选择（嘌呤含量查附录1 表格）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=6" target="_blank" rel="noreferrer">三(一)</a>、<a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=13" target="_blank" rel="noreferrer">附录1</a></td></tr><tr><td>买既往没诱发过痛风发作的食物；避免个人诱因食物</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=6" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>优先菊苣、鲜百合等蔬菜，樱桃、草莓等富含维 C 的水果</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>不买含糖饮料、鲜榨果汁、果葡糖浆、果脯蜜饯等高果糖食品</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>不买腊制、腌制、熏制肉类（嘌呤与盐分高）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>【本站提示】买包装饮品认准&quot;无糖&quot;，避开果葡糖浆配料</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr></tbody></table><h3 id="🍳-做" tabindex="-1">🍳 做 <a class="header-anchor" href="#🍳-做" aria-label="Permalink to &quot;🍳 做&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>少盐少油、减少调味品、清淡膳食</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>肉类先<strong>汆煮</strong>后烹调、尽量不喝汤（嘌呤溶于水）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>减少油炸、煎制、卤制</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>【本站提示】&quot;汆煮去嘌呤&quot;：肉类切块冷水下锅焯 3～5 分钟弃汤再烧</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr></tbody></table><h3 id="🍚-吃" tabindex="-1">🍚 吃 <a class="header-anchor" href="#🍚-吃" aria-label="Permalink to &quot;🍚 吃&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么吃</th><th>出处</th></tr></thead><tbody><tr><td>全谷物不低于主食量 30%</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=6" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>每天蔬菜 ≥500g、深色过半；奶 300mL 以上</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>水果 200～350g 正常吃（水果摄入量与痛风无显著相关性）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>白水为主，也可柠檬水、淡茶、无糖咖啡、苏打水；避免浓茶浓咖啡与生冷饮品</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>限制饮酒：黄酒嘌呤较高、啤酒次之，白酒易致乳酸堆积；<strong>急性发作期、药物控制不佳或慢性痛风性关节炎患者不饮酒</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>少吃生冷食品（冰淇淋、生冷海鲜等）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>调理脾胃食材：白扁豆、玉米须、麦芽、山药、芡实、大枣、橘皮、山楂、五指毛桃、茯苓</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=10" target="_blank" rel="noreferrer">三(六)</a></td></tr><tr><td>按证型施膳：如湿浊证（常见于无症状期与间歇期）严格控制肥甘厚味、低盐膳食、避免甜腻酸涩</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=10" target="_blank" rel="noreferrer">三(六)</a></td></tr></tbody></table><h3 id="🏃-动" tabindex="-1">🏃 动 <a class="header-anchor" href="#🏃-动" aria-label="Permalink to &quot;🏃 动&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么动</th><th>出处</th></tr></thead><tbody><tr><td>低、中强度有氧为主，每周 4～5 次、每次 30～60 分钟；慢跑、走路、骑车、太极拳、八段锦、游泳</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=9" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>适量力量和柔韧性练习；运动期间或运动后及时补水</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=9" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td><strong>痛风性关节炎期应减少或避免运动</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=9" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>规律作息、劳逸结合，避免疲劳</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=9" target="_blank" rel="noreferrer">三(五)</a></td></tr></tbody></table><h3 id="🩺-测与就医" tabindex="-1">🩺 测与就医 <a class="header-anchor" href="#🩺-测与就医" aria-label="Permalink to &quot;🩺 测与就医&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>定期监测血尿酸，遵医嘱治疗</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=9" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>避免过度节食和减重过快（每周 0.5～1.0kg 为宜）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=9" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>因地因时择膳相宜，结合季节与地域调整</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=11" target="_blank" rel="noreferrer">三(七)</a></td></tr></tbody></table><h2 id="常见误区-原文明确告诫" tabindex="-1">常见误区（原文明确告诫） <a class="header-anchor" href="#常见误区-原文明确告诫" aria-label="Permalink to &quot;常见误区（原文明确告诫）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>原文怎么说</th><th>出处</th></tr></thead><tbody><tr><td>&quot;水果含果糖，痛风不能吃&quot;</td><td>水果的维 C、黄酮、多酚等可改变果糖影响，摄入量与痛风无显著相关性；要限的是含糖饮料、果汁、蜜饯</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=7" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>&quot;白酒嘌呤低可以喝&quot;</td><td>白酒酒精度高、易使乳酸堆积抑制尿酸排泄；应限制饮酒</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>&quot;喝肉汤补身体&quot;</td><td>肉类汆煮后食用、尽量不喝汤（嘌呤溶于汤水）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>&quot;减重越快越好&quot;</td><td>避免过度节食和减重过快，每周 0.5～1.0kg 为宜</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=9" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>&quot;痛着也要坚持锻炼&quot;</td><td>痛风性关节炎期应减少或避免运动</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=9" target="_blank" rel="noreferrer">三(五)</a></td></tr></tbody></table><h2 id="分期食谱与工具怎么用" tabindex="-1">分期食谱与工具怎么用 <a class="header-anchor" href="#分期食谱与工具怎么用" aria-label="Permalink to &quot;分期食谱与工具怎么用&quot;">​</a></h2><ul><li><strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=13" target="_blank" rel="noreferrer">附录1《常见食物嘌呤含量》</a></strong>：按类查食物嘌呤水平，选低嘌呤食材。</li><li><strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=20" target="_blank" rel="noreferrer">附录2《食物选择》</a></strong>：推荐吃与不建议吃的清单。</li><li><strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=22" target="_blank" rel="noreferrer">附录3《不同阶段不同地区不同季节食谱示例》</a></strong>：先分清自己所处阶段（无症状高尿酸血症期与痛风间歇期 / 急性期及慢性期），再按地区、季节取食谱。</li><li><strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=63" target="_blank" rel="noreferrer">附录4《常见食物交换表》</a></strong>：同类食物等量交换。</li><li><strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/gout-2024.pdf#page=69" target="_blank" rel="noreferrer">附录5《食养方举例》</a></strong>：辨证使用，食用方法请咨询医师等专业人员。</li></ul><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>国家卫生健康委办公厅</td></tr><tr><td>版本</td><td>2024 年版（现行）</td></tr><tr><td>印发时间</td><td>2024 年 2 月</td></tr><tr><td>原文直链</td><td><a href="https://www.nhc.gov.cn/wjw/c100378/202402/afd5dda4bd6745fda10aad8d43a16369/files/1732845129551_37712.pdf" target="_blank" rel="noreferrer">卫健委官网 PDF</a></td></tr></tbody></table>',26)])])}const n=e(g,[["render",h]]);export{p as __pageData,n as default};
